Your expense tracker is below. Add items with a category and amount, set a monthly budget, and it shows your total, what's left and spending by category. Entries clear when you close the page, so it's best for a quick check.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#1c1c1e}
h2{margin:0 0 12px;font-size:18px}
.card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:8px}
input{flex:1;min-width:90px}
button{background:#0f6cbd;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00020;padding:2px 8px}
.big{font-size:22px;font-weight:600}
.muted{color:#666;font-size:13px}
.bar{height:8px;background:#e3e3e8;border-radius:4px;overflow:hidden;margin:4px 0 10px}
.bar i{display:block;height:100%;background:#0f6cbd}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.over{color:#b00020}
</style></head><body>
<div class="card">
  <h2>Monthly budget</h2>
  <div class="row"><input id="budget" type="number" placeholder="Budget in ₹" value="50000" oninput="draw()"></div>
  <div style="margin-top:10px" class="row">
    <div style="flex:1"><div class="muted">Spent</div><div class="big" id="spent">₹0</div></div>
    <div style="flex:1"><div class="muted">Left</div><div class="big" id="left">₹0</div></div>
  </div>
  <div class="bar"><i id="pbar" style="width:0%"></i></div>
</div>
<div class="card">
  <h2>Add an expense</h2>
  <div class="row">
    <input id="name" placeholder="What for?">
    <input id="amt" type="number" placeholder="Amount ₹">
  </div>
  <div class="row" style="margin-top:8px">
    <select id="cat" style="flex:1">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button onclick="add()">Add</button>
  </div>
</div>
<div class="card"><h2>By category</h2><div id="cats" class="muted">Nothing yet.</div></div>
<div class="card"><h2>All expenses</h2><div id="list" class="muted">Nothing yet.</div></div>
<script>
var items=[];
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function add(){
  var n=document.getElementById('name').value.trim();
  var a=parseFloat(document.getElementById('amt').value);
  if(!n||!(a>0))return;
  items.push({n:n,a:a,c:document.getElementById('cat').value});
  document.getElementById('name').value='';
  document.getElementById('amt').value='';
  draw();
}
function del(i){items.splice(i,1);draw();}
function draw(){
  var total=0,by={};
  items.forEach(function(x){total+=x.a;by[x.c]=(by[x.c]||0)+x.a;});
  var b=parseFloat(document.getElementById('budget').value)||0;
  document.getElementById('spent').textContent=inr(total);
  var l=document.getElementById('left');
  l.textContent=inr(b-total);
  l.className='big'+(b-total<0?' over':'');
  document.getElementById('pbar').style.width=(b>0?Math.min(100,total/b*100):0)+'%';
  var c='';
  Object.keys(by).sort(function(x,y){return by[y]-by[x];}).forEach(function(k){
    c+='<div class="item" style="border:0;padding:0"><span>'+esc(k)+'</span><span>'+inr(by[k])+'</span></div><div class="bar"><i style="width:'+(by[k]/total*100)+'%"></i></div>';
  });
  document.getElementById('cats').innerHTML=c||'Nothing yet.';
  var h='';
  items.forEach(function(x,i){
    h+='<div class="item"><span>'+esc(x.n)+' <span class="muted">· '+esc(x.c)+'</span></span><span>'+inr(x.a)+' <button class="x" onclick="del('+i+')">✕</button></span></div>';
  });
  document.getElementById('list').innerHTML=h||'Nothing yet.';
}
draw();
</script>
</body></html>
```

